def estimate_tokens(text: str) -> int:
    # Empty input costs no tokens at all.
    if not text:
        return 0
    # Common rule of thumb: about 4 characters per token for English text.
    approx = len(text) // 4
    # Any non-empty string is worth at least one token, so apply a floor of 1.
    return max(1, approx)

