def trim_history(messages: list[dict], budget: int) -> list[dict]:
    # Local token estimator mirroring the chars-per-token heuristic.
    def cost(msg):
        return max(1, len(msg["content"]) // 4)

    # Work on a copy so we do not mutate the caller's list.
    kept = list(messages)
    # Total cost of everything currently kept.
    total = sum(cost(m) for m in kept)
    # Remove from the front (oldest) until we are within budget or empty.
    while kept and total > budget:
        removed = kept.pop(0)
        total -= cost(removed)
    return kept

