def rrf(list_a, list_b, k=60):
    # Accumulate the fused score for each id.
    scores = {}
    # Track the order an id was first seen so ties are broken deterministically.
    first_seen = {}
    order = 0
    # Process both ranked lists; rank is the 0-based position.
    for ranked in (list_a, list_b):
        for rank, item in enumerate(ranked):
            # Standard RRF contribution for this rank.
            scores[item] = scores.get(item, 0.0) + 1.0 / (k + rank)
            if item not in first_seen:
                first_seen[item] = order
                order += 1
    # Sort by score descending, then by earliest appearance ascending.
    fused = sorted(scores, key=lambda item: (-scores[item], first_seen[item]))
    return fused

