def validate_args(args: dict, schema: dict) -> list[str]:
    # Map the schema's type names to real Python types.
    type_map = {"str": str, "int": int, "float": float, "bool": bool}
    errors = []
    # 1) Every required key must be present.
    for key in schema.get("required", []):
        if key not in args:
            errors.append(f"missing required key: {key}")
    # 2) Each present key that has a declared type must match it.
    for key, type_name in schema.get("types", {}).items():
        if key not in args:
            continue
        expected = type_map.get(type_name)
        value = args[key]
        # bool is a subclass of int in Python; treat it strictly by exact type.
        if expected is not None and type(value) is not expected:
            errors.append(f"wrong type for {key}")
    return errors

