def retry(fn, max_attempts, base_delay=1.0, sleep=None):
    # Default sleep is a no-op so the function is deterministic and testable.
    if sleep is None:
        sleep = lambda seconds: None
    delays = []
    last_error = None
    for attempt in range(1, max_attempts + 1):
        try:
            # Success: return the result and the delays we already waited.
            return fn(), delays
        except Exception as exc:
            last_error = exc
            # If more attempts remain, wait with exponential backoff.
            if attempt < max_attempts:
                delay = base_delay * (2 ** (attempt - 1))
                delays.append(delay)
                sleep(delay)
    # Every attempt failed: propagate the last exception.
    raise last_error

