def parse_react(trace: str) -> list[dict]:
    steps = []
    current = None
    for raw in trace.splitlines():
        line = raw.strip()
        # Skip empty lines entirely.
        if not line:
            continue
        if line.startswith("Thought:"):
            # A Thought starts a brand new step.
            current = {"thought": line[len("Thought:"):].strip(),
                       "action": None, "observation": None}
            steps.append(current)
        elif line.startswith("Action:") and current is not None:
            current["action"] = line[len("Action:"):].strip()
        elif line.startswith("Observation:") and current is not None:
            current["observation"] = line[len("Observation:"):].strip()
        # Unknown prefixes (or lines before the first Thought) are ignored.
    return steps

