class StreamAccumulator:
    def __init__(self):
        # Collect deltas in a list for efficient appends, join lazily.
        self._parts = []
        self._done = False

    def push(self, delta):
        # Once finished, no more tokens may arrive.
        if self._done:
            raise RuntimeError("stream already finished")
        self._parts.append(delta)

    def finish(self):
        # Mark the stream as complete; idempotent.
        self._done = True

    def text(self):
        # Join accumulated deltas into the current full text.
        return "".join(self._parts)

    def is_done(self):
        return self._done

