class IdempotentRunner:
    def __init__(self):
        # Maps an idempotency key to the result produced the first time.
        self._cache = {}

    def run(self, key, fn):
        # If we have already run this key, return the stored result.
        if key in self._cache:
            return self._cache[key]
        # First time for this key: execute, cache, and return.
        result = fn()
        self._cache[key] = result
        return result

