from collections import deque


class WindowMemory:
    def __init__(self, n):
        # deque with maxlen automatically drops the oldest item when full.
        self._turns = deque(maxlen=n)

    def add(self, turn):
        # Appending past capacity evicts from the left (oldest) end.
        self._turns.append(turn)

    def history(self):
        # Return a plain list, oldest-first, matching insertion order.
        return list(self._turns)

