solutionCode:
def judge(answer: str, expected_keywords: list[str]) -> float:
    # No criteria means nothing to fail on -> perfect score.
    if not expected_keywords:
        return 1.0
    # Case-insensitive matching by lowercasing once.
    haystack = answer.lower()
    # Count how many expected keywords appear as substrings.
    hits = sum(1 for kw in expected_keywords if kw.lower() in haystack)
    # Coverage fraction, rounded to two decimals for stable comparisons.
    return round(hits / len(expected_keywords), 2)
